/* Signature Irish Gaelic Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Seanmhair": "From sean (old, wise).", "Siobhanrinn": "From Siobhan + rinn (point/star?).", "Padraigceol": "From Padraig + ceol (music).", "Aoifebhan": "From Aoife + ban (white): 'radiant white'.", "Cianog": "From Cian + -og (young).", "Niamhdonn": "From Niamh + donn (brown/noble).", "O'Seanmhair": "Signature surname in O style.", "MacPadraigceol": "Signature surname in Mac style.", "Ni Aoifebhan": "Signature feminine surname in Ni style.", "Nic Niamhdonn": "Signature feminine surname in Nic style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Seanmhair';
console.log(lookup(q));

